public class Animal { public virtual void Speak() { Console.WriteLine("Animal"); } }
public class Dog : Animal { public override void Speak() { Console.WriteLine("Woof"); } }
public class Cat : Animal { public override void Speak() { Console.WriteLine("Meow"); } }

Animal[] animals = { new Dog(), new Cat() };
foreach (var a in animals)
    a.Speak();

public class Animal
{
    public virtual void Move()
    {
        Console.WriteLine("Animal moves");
    }
}

var a = new Animal();
a.Move();  // prints 'Animal moves'

public class Dog : Animal
{
    public override void Move()
    {
        Console.WriteLine("Dog runs");
    }
}

Animal a = new Dog();
a.Move();  // prints 'Dog runs' - not 'Animal moves'

