slides.example:
public class Animal
{
    public void Speak() { Console.WriteLine("Animal"); }
}

public class Dog : Animal
{
    public new void Speak() { Console.WriteLine("Woof"); }
}

Animal a = new Dog();
a.Speak();  // prints 'Animal' (compile-time!)

Dog d = new Dog();
d.Speak();  // prints 'Woof'

public abstract class Animal
{
    public string Name;
    public abstract void MakeSound(); // no body
}

public class Dog : Animal
{
    public override void MakeSound() { Console.WriteLine("Woof"); }
}

Animal a = new Dog();
a.MakeSound();  // Woof

public class Dog : Animal
{
    public override void Move()
    {
        base.Move();  // Call Animal.Move()
        Console.WriteLine("and then runs");
    }
}

Animal a = new Dog();
a.Move();  // 'Animal moves' then 'and then runs'

